import { Controller, Get, Post, Body } from '@nestjs/common';
import { Authenticate, CurrentUser } from '@nestjs/authentication';

@Controller('orders')
export class OrdersController {
  constructor(private readonly ordersService: OrdersService) {}

  @Get()
  findMine(@CurrentUser() user: User) {
    return this.ordersService.findMine(user.id);
  }

  // 收据和物流通知发到客户邮箱，必须是已验证地址
  @Authenticate({ verifiedEmail: true })
  @Post()
  place(@CurrentUser('id') userId: string, @Body('items') items: OrderItem[]) {
    return this.ordersService.place(userId, items);
  }
}

import { Policy, type PolicyBefore } from '@nestjs/authorization';

const isStaff = (user: User | null) => !!user?.roles.includes('staff');

@Policy()
export class ProductPolicy implements PolicyBefore<User> {
  // 返回 true 放行、false 拒绝、undefined 交给 ability 决定
  before(user: User | null) {
    return user?.roles.includes('admin') ? true : undefined;
  }

  // null 表示访客：所有人看已发布商品，员工还能看草稿
  view(user: User | null, product: Product) {
    return product.published || isStaff(user);
  }

  create(user: User | null) {
    return isStaff(user);
  }

  delete(user: User | null) {
    return isStaff(user);
  }
}

import { Body, Controller, Delete, Get, Param, Post } from '@nestjs/common';
import { Can } from '@nestjs/authorization';
import { CurrentUser } from '@nestjs/authentication';

@Controller('products')
export class ProductsController {
  constructor(private readonly productsService: ProductsService) {}

  @Get(':id')
  @Can.Anyone()
  findOne(@CurrentUser() user: User | null, @Param('id') id: string) {
    return this.productsService.findOne(user, id);
  }

  @Post()
  @Can(ProductPolicy, 'create')
  create(@Body() input: CreateProductDto) {
    return this.productsService.create(input);
  }

  @Delete(':id')
  @Can(ProductPolicy, 'delete')
  remove(@Param('id') id: string) {
    return this.productsService.remove(id);
  }
}

import { createCipheriv, createDecipheriv, randomBytes, scrypt } from 'node:crypto';
import { promisify } from 'node:util';

const iv = randomBytes(16);
const password = 'Password used to generate key';

// 密钥长度取决于算法：aes-256 需要 32 字节
const key = (await promisify(scrypt)(password, 'salt', 32)) as Buffer;
const cipher = createCipheriv('aes-256-ctr', key, iv);

const textToEncrypt = 'Nest';
const encryptedText = Buffer.concat([
  cipher.update(textToEncrypt),
  cipher.final(),
]);

const decipher = createDecipheriv('aes-256-ctr', key, iv);
const decryptedText = Buffer.concat([
  decipher.update(encryptedText),
  decipher.final(),
]).toString();

import { Injectable } from '@nestjs/common';
import { PasswordHasher } from '@nestjs/authentication';

@Injectable()
export class CredentialsService {
  constructor(private readonly passwordHasher: PasswordHasher) {}

  hashPassword(password: string) {
    return this.passwordHasher.hash(password);
  }

  async checkPassword(password: string, storedHash: string | undefined) {
    const ok = await this.passwordHasher.verify(password, storedHash);
    if (ok && this.passwordHasher.needsRehash(storedHash)) {
      // 登录成功且仍持有明文时，把旧哈希升级到当前成本
      return { ok, upgradedHash: await this.passwordHasher.hash(password) };
    }
    return { ok };
  }
}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module.js';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  // 必须在 init()/listen() 之前调用，且只能调用一次
  app.useSecurityHeaders({
    xFrameOptions: { action: 'deny' },
    strictTransportSecurity: { maxAge: 63072000, preload: true },
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  });

  await app.listen(process.env.PORT ?? 3000);
}
bootstrap();

app.useSecurityHeaders({
  contentSecurityPolicy: {
    useDefaults: false,
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", 'https://cdn.example.com'],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:'],
      // 生产环境走 HTTPS 时才有意义，纯 HTTP 可去掉
      upgradeInsecureRequests: null,
    },
  },
});

